def score(c,s):
 *L,T=c.split('\n');W=len(L[0]);b=max(y.find('o')for y in L);E=[]
 for y in L:
  m=[i for i,x in enumerate(y)if'@'<x<'[']
  if m:
   o=m[0];g=m[1]-o;q=(b-o)%g;F=q<=W-3-m[-1];G=g-q<=o-2
   d=0 if not q else(q if F else q-g if G else 0)if q+q<g else(q-g if G else q if F else 0)
   x=['-']*(W-4)
   for i in m:x[i-2+d]=y[i]
   y='=|'+''.join(x)+'|='
  E+=[y.rstrip()]
 A=[z.rstrip()for z in s.rstrip().split('\n')]
 return int(A==E or A==E+[T])
